"""Authentication endpoints: register, login, current user."""

from __future__ import annotations

import re
import sqlite3

from fastapi import APIRouter, Depends, status
from pydantic import BaseModel

from app.config import Settings, get_settings
from app.db import get_db, utc_now, audit
from app.errors import bad_request, conflict, unauthorized
from app.security import (
    hash_password,
    verify_password,
    create_access_token,
    password_problem,
    get_current_user,
    CurrentUser,
)

router = APIRouter(prefix="/api/auth", tags=["auth"])

USERNAME_RE = re.compile(r"^[A-Za-z0-9_-]{3,32}$")


class RegisterIn(BaseModel):
    username: str
    password: str


class UserOut(BaseModel):
    id: int
    username: str
    created_at: str


class LoginIn(BaseModel):
    username: str
    password: str


class TokenOut(BaseModel):
    access_token: str
    token_type: str = "bearer"
    expires_in: int


@router.post(
    "/register",
    response_model=UserOut,
    status_code=status.HTTP_201_CREATED,
    summary="Create a new account",
)
def register(
    data: RegisterIn,
    conn: sqlite3.Connection = Depends(get_db),
    settings: Settings = Depends(get_settings),
) -> UserOut:
    username = data.username.strip()
    password = data.password

    if not USERNAME_RE.fullmatch(username):
        raise bad_request("invalid_username", "Username must be 3-32 letters, digits, _ or -.")

    prob = password_problem(password)
    if prob:
        raise bad_request("weak_password", prob)

    cur = conn.execute("SELECT id FROM users WHERE username = ? COLLATE NOCASE", (username,))
    if cur.fetchone():
        raise conflict("username_taken", "That username is already taken.")

    now = utc_now()
    pw_hash = hash_password(password)
    cur = conn.execute(
        "INSERT INTO users (username, password_hash, created_at) VALUES (?, ?, ?)",
        (username, pw_hash, now),
    )
    user_id = cur.lastrowid
    audit(conn, "register", user_id, f"username={username}")
    return UserOut(id=user_id, username=username, created_at=now)


@router.post("/login", response_model=TokenOut, summary="Sign in and get an access token")
def login(
    data: LoginIn,
    conn: sqlite3.Connection = Depends(get_db),
    settings: Settings = Depends(get_settings),
) -> TokenOut:
    username = data.username.strip()
    password = data.password

    cur = conn.execute("SELECT id, password_hash FROM users WHERE username = ? COLLATE NOCASE", (username,))
    row = cur.fetchone()

    if row and verify_password(password, row["password_hash"]):
        user_id = row["id"]
        token = create_access_token(user_id, username, settings)
        audit(conn, "login", user_id, f"username={username}")
        return TokenOut(access_token=token, expires_in=settings.token_ttl)

    audit(conn, "login_failed", None, f"username={username}")
    raise unauthorized("invalid_credentials", "Invalid username or password.")


@router.get("/me", response_model=UserOut, summary="Current signed-in user")
def me(user: CurrentUser = Depends(get_current_user)) -> UserOut:
    cur = get_db().__next__()
    try:
        row = cur.execute("SELECT created_at FROM users WHERE id = ?", (user.id,)).fetchone()
        created_at = row["created_at"] if row else ""
    finally:
        pass
    return UserOut(id=user.id, username=user.username, created_at=created_at)
