"""Todo endpoints for the signed-in user."""

from __future__ import annotations

import sqlite3

from fastapi import APIRouter, Depends, status
from pydantic import BaseModel, Field

from app.config import Settings, get_settings
from app.db import get_db, utc_now, row_to_dict
from app.errors import not_found
from app.pagination import PageParams, page_params, paginate
from app.security import get_current_user, CurrentUser

router = APIRouter(prefix="/api/todos", tags=["todos"])


class TodoIn(BaseModel):
    title: str = Field(min_length=1, max_length=200)


class TodoPatch(BaseModel):
    title: str | None = Field(default=None, min_length=1, max_length=200)
    done: bool | None = None


class TodoOut(BaseModel):
    id: int
    title: str
    done: bool
    created_at: str
    updated_at: str


def _todo_row_to_out(row: sqlite3.Row) -> TodoOut:
    return TodoOut(
        id=row["id"],
        title=row["title"],
        done=bool(row["done"]),
        created_at=row["created_at"],
        updated_at=row["updated_at"],
    )


@router.get("", response_model=dict, summary="List todos (paged, newest first)")
def list_todos(
    done: bool | None = None,
    page: PageParams = Depends(page_params),
    user: CurrentUser = Depends(get_current_user),
    conn: sqlite3.Connection = Depends(get_db),
) -> dict:
    params: list = [user.id]
    where = "WHERE user_id = ?"
    if done is not None:
        where += " AND done = ?"
        params.append(1 if done else 0)

    total = conn.execute(f"SELECT COUNT(*) FROM todos {where}", params).fetchone()[0]

    sql = f"""
        SELECT id, title, done, created_at, updated_at
        FROM todos
        {where}
        ORDER BY created_at DESC
        LIMIT ? OFFSET ?
    """
    params.extend([page.limit, page.offset])
    rows = conn.execute(sql, params).fetchall()
    items = [_todo_row_to_out(r) for r in rows]
    return paginate(items, total, page)


@router.post("", response_model=TodoOut, status_code=status.HTTP_201_CREATED, summary="Create a todo")
def create_todo(
    data: TodoIn,
    user: CurrentUser = Depends(get_current_user),
    conn: sqlite3.Connection = Depends(get_db),
) -> TodoOut:
    title = data.title.strip()
    now = utc_now()
    cur = conn.execute(
        "INSERT INTO todos (user_id, title, done, created_at, updated_at) VALUES (?, ?, 0, ?, ?)",
        (user.id, title, now, now),
    )
    todo_id = cur.lastrowid
    row = conn.execute(
        "SELECT id, title, done, created_at, updated_at FROM todos WHERE id = ?",
        (todo_id,),
    ).fetchone()
    return _todo_row_to_out(row)


@router.get("/{todo_id}", response_model=TodoOut, summary="Get a todo")
def get_todo(
    todo_id: int,
    user: CurrentUser = Depends(get_current_user),
    conn: sqlite3.Connection = Depends(get_db),
) -> TodoOut:
    row = conn.execute(
        "SELECT id, title, done, created_at, updated_at FROM todos WHERE id = ? AND user_id = ?",
        (todo_id, user.id),
    ).fetchone()
    if not row:
        raise not_found("todo_not_found", "Todo not found.")
    return _todo_row_to_out(row)


@router.patch("/{todo_id}", response_model=TodoOut, summary="Update a todo")
def update_todo(
    todo_id: int,
    data: TodoPatch,
    user: CurrentUser = Depends(get_current_user),
    conn: sqlite3.Connection = Depends(get_db),
) -> TodoOut:
    row = conn.execute(
        "SELECT id, title, done, created_at, updated_at FROM todos WHERE id = ? AND user_id = ?",
        (todo_id, user.id),
    ).fetchone()
    if not row:
        raise not_found("todo_not_found", "Todo not found.")

    title = data.title.strip() if data.title is not None else row["title"]
    done = 1 if data.done else 0 if data.done is not None else row["done"]
    now = utc_now()

    conn.execute(
        "UPDATE todos SET title = ?, done = ?, updated_at = ? WHERE id = ?",
        (title, done, now, todo_id),
    )
    row = conn.execute(
        "SELECT id, title, done, created_at, updated_at FROM todos WHERE id = ?",
        (todo_id,),
    ).fetchone()
    return _todo_row_to_out(row)


@router.delete("/{todo_id}", status_code=status.HTTP_204_NO_CONTENT, summary="Delete a todo")
def delete_todo(
    todo_id: int,
    user: CurrentUser = Depends(get_current_user),
    conn: sqlite3.Connection = Depends(get_db),
) -> None:
    cur = conn.execute(
        "DELETE FROM todos WHERE id = ? AND user_id = ?",
        (todo_id, user.id),
    )
    if cur.rowcount == 0:
        raise not_found("todo_not_found", "Todo not found.")
