        actions.append(toggleBtn, renameBtn, deleteBtn);
        li.append(title, actions);
        list.appendChild(li);
      }
    }

    function updatePager() {
      const page = Math.floor(offset / PAGE_SIZE) + 1;
      const totalPages = Math.ceil(total / PAGE_SIZE) || 1;
      pageInfo.textContent = `Page ${page} of ${totalPages} (${total} total)`;
      prevBtn.disabled = offset === 0;
      nextBtn.disabled = offset + PAGE_SIZE >= total;
    }

    prevBtn.addEventListener("click", () => {
      offset = Math.max(0, offset - PAGE_SIZE);
      loadTodos();
    });

    nextBtn.addEventListener("click", () => {
      offset += PAGE_SIZE;
      loadTodos();
    });

    addForm.addEventListener("submit", async (e) => {
      e.preventDefault();
      await whileBusy(addForm, async () => {
        const data = formValues(addForm);
        try {
          await apiFetch("/api/todos", { method: "POST", body: data });
          addForm.reset();
          offset = 0;
          loadTodos();
        } catch (err) {
          showMessage(err.message || "Failed to add todo.", "error");
        }
      });
    });

    async function toggleTodo(id, done) {
      try {
        await apiFetch(`/api/todos/${id}`, { method: "PATCH", body: { done } });
        loadTodos();
      } catch (err) {
        showMessage(err.message || "Failed to update todo.", "error");
      }
    }

    async function renameTodo(id, currentTitle) {
      const newTitle = prompt("Rename todo:", currentTitle);
      if (newTitle === null || newTitle.trim() === currentTitle.trim()) return;
      const title = newTitle.trim();
      if (!title) {
        showMessage("Title cannot be empty.", "error");
        return;
      }
      try {
        await apiFetch(`/api/todos/${id}`, { method: "PATCH", body: { title } });
        loadTodos();
      } catch (err) {
        showMessage(err.message || "Failed to rename todo.", "error");
      }
    }

    async function deleteTodo(id) {
      if (!confirm("Delete this todo?")) return;
      try {
        await apiFetch(`/api/todos/${id}`, { method: "DELETE" });
        loadTodos();
      } catch (err) {
        showMessage(err.message || "Failed to delete todo.", "error");
      }
    }

    signoutBtn.addEventListener("click", () => {
      clearToken();
      location.href = "login.html";
    });

    loadUser();
    loadTodos();
  </script>
</body>
